def priority(item: float, bins: np.ndarray) -> np.ndarray:
    current_fill = bins - item
    fill_ratio = current_fill / bins
    deviation_from_half = np.abs(fill_ratio - 0.5)
    return 1.0 / (1 + deviation_from_half**2)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_capacity = bins - item
    remaining_capacity = np.maximum(remaining_capacity, 1e-10)
    target_fill = (bins + item) / 2
    deviation_from_target = np.abs(remaining_capacity - target_fill)
    return 1.0 / (1.0 + np.log1p(deviation_from_target))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_ratio = 0.7
    remaining_capacity = bins - item
    remaining_ratio = remaining_capacity / bins
    return -np.abs(remaining_ratio - target_ratio)
